	static class PcodeHtmlFormatter : AbstractPcodeFormatter<string, PcodeHtmlAppender> {
		private Language language;
		private PcodeFrame frame;

		public PcodeHtmlFormatter(PcodeThread<object> thread) {
			this.language = thread.getLanguage();
			PcodeProgram nop = thread.getMachine().compileSleigh("nothing", "");
			this.frame = thread.getExecutor().begin(nop);
		}

		string getHtml() {
			return formatOps(language, frame.getCode());
		}

		/* @Override */
		protected PcodeHtmlAppender createAppender(Language lang, bool indent) {
			return new PcodeHtmlAppender(lang, frame);
		}

		string formatOp(PcodeOp op) {
			OpTpl tpl = PcodeFormatter.getPcodeOpTemplateLog(language.getAddressFactory(), op);
			PcodeHtmlAppender appender = createAppender(language, false);
			formatOpTemplate(appender, tpl);
			return appender.finish();
		}
	}

	private Z3SummaryProvider provider;

	protected PcodeLogTableModel model;
	protected GTable table;
	protected GhidraTableFilterPanel<RecOp> filterPanel;

	public Z3SummaryPcodeLogPanel(Z3SummaryProvider provider) : base(new BorderLayout())
    {
		this.provider = provider;

		model = new PcodeLogTableModel(provider.getTool());
		table = new GTable(model);
		add(new JScrollPane(table));

		filterPanel = new(table, model);
		add(filterPanel, BorderLayout.SOUTH);

		table.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
		table.addMouseListener(new _Anon_MouseAdapter_1());
		table.addKeyListener(new _Anon_KeyAdapter_2());
	}

	private void fireSelectedAddress() {
		RecOp sel = filterPanel.getSelectedItem();
		if (sel == null) {
			return;
		}
		provider.fireAddress(sel.getAddress());
	}

	public void setLog(List<RecOp> log) {
		model.clear();
		model.addAll(log);
	}

	internal class _Anon_MouseAdapter_1 : MouseAdapter
	{

			/* @Override */
			public void mouseClicked(MouseEvent e) {
				if (e.getClickCount() != 2) {
					return;
				}
				e.consume();
				fireSelectedAddress();
			}
		
	}


	internal class _Anon_KeyAdapter_2 : KeyAdapter
	{

			/* @Override */
			public void keyPressed(KeyEvent e) {
				if (e.getKeyCode() != KeyEvent.VK_ENTER) {
					return;
				}
				e.consume();
				fireSelectedAddress();
			}
		
	}

